    Art.initTest(Arch.FrigateThreatResponseCoordinator_Instance_threatResponseProcess_defenseReadinessAssessor)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.FrigateThreatResponseCoordinator_Instance_threatResponseProcess_defenseReadinessAssessor)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.FrigateThreatResponseCoordinator_Instance_threatResponseProcess_defenseReadinessAssessor)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.FrigateThreatResponseCoordinator_Instance_threatResponseProcess_defenseReadinessAssessor)
  }

  /** helper function to set the values of all input ports.
   * @param defenseEvidence payload for data port defenseEvidence
   */
  def put_concrete_inputs(defenseEvidence : Frigate_Threat_Response_Coordinator.DefenseEvidence): Unit = {
    put_defenseEvidence(defenseEvidence)
  }


  /** helper function to check DefenseReadinessAssessor_threatResponseProcess_defenseReadinessAssessor's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param defenseCondition method that will be called with the value of the outgoing data
   *        port 'defenseCondition'.
   */
  def check_concrete_output(defenseCondition: Frigate_Threat_Response_Coordinator.DefenseCondition.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val defenseConditionValue: Frigate_Threat_Response_Coordinator.DefenseCondition.Type = get_defenseCondition().get
    if(!defenseCondition(defenseConditionValue)) {
      testFailures = testFailures :+ st"'defenseCondition' did not match expected: value of the outgoing data port is ${defenseConditionValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_defenseEvidence(value : Frigate_Threat_Response_Coordinator.DefenseEvidence): Unit = {
    Art.insertInInfrastructurePort(Arch.FrigateThreatResponseCoordinator_Instance_threatResponseProcess_defenseReadinessAssessor.operational_api.defenseEvidence_Id, Frigate_Threat_Response_Coordinator.DefenseEvidence_Payload(value))
  }

  // getter for out DataPort
  def get_defenseCondition(): Option[Frigate_Threat_Response_Coordinator.DefenseCondition.Type] = {
    val value: Option[Frigate_Threat_Response_Coordinator.DefenseCondition.Type] = get_defenseCondition_payload() match {
      case Some(Frigate_Threat_Response_Coordinator.DefenseCondition_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port defenseCondition.  Expecting 'Frigate_Threat_Response_Coordinator.DefenseCondition_Payload' but received ${v}")
      case _ => None[Frigate_Threat_Response_Coordinator.DefenseCondition.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_defenseCondition_payload(): Option[Frigate_Threat_Response_Coordinator.DefenseCondition_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.FrigateThreatResponseCoordinator_Instance_threatResponseProcess_defenseReadinessAssessor.initialization_api.defenseCondition_Id).asInstanceOf[Option[Frigate_Threat_Response_Coordinator.DefenseCondition_Payload]]
